ALTER TABLE public.campaigns ADD COLUMN IF NOT EXISTS first_launched_at timestamptz;
UPDATE public.campaigns SET first_launched_at=created_at WHERE first_launched_at IS NULL AND status IN ('sending','sent','paused','cancelled','failed');
CREATE OR REPLACE FUNCTION public.capture_campaign_first_launch() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN NEW.first_launched_at:=OLD.first_launched_at; END IF; IF NEW.first_launched_at IS NULL AND NEW.status IN ('sending','sent') THEN NEW.first_launched_at:=now(); END IF; RETURN NEW; END $$;
CREATE TRIGGER campaign_first_launch BEFORE INSERT OR UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION public.capture_campaign_first_launch();
CREATE INDEX IF NOT EXISTS campaigns_account_first_launch_idx ON public.campaigns(account_id,first_launched_at) WHERE first_launched_at IS NOT NULL;
ALTER TABLE public.support_tickets ADD COLUMN IF NOT EXISTS merged_into_ticket_id uuid REFERENCES public.support_tickets(id);
CREATE OR REPLACE FUNCTION public.create_or_append_support_ticket(_account_id uuid,_email text,_name text,_subject text,_topic text,_message text,_source text,_previous uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.support_tickets; BEGIN IF _source NOT IN ('app','contact','email') OR length(trim(_message))<1 OR length(_message)>8000 OR length(trim(_email))<3 THEN RAISE EXCEPTION 'Invalid support request'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(COALESCE(_account_id::text,lower(trim(_email))),0)); SELECT * INTO t FROM public.support_tickets WHERE status IN ('open','waiting') AND merged_into_ticket_id IS NULL AND ((_account_id IS NOT NULL AND account_id=_account_id) OR (_account_id IS NULL AND account_id IS NULL AND lower(requester_email)=lower(trim(_email)))) ORDER BY created_at,id LIMIT 1 FOR UPDATE; IF t.id IS NOT NULL THEN INSERT INTO public.support_ticket_messages(ticket_id,author,body,via) VALUES(t.id,'customer','Additional request: '||left(_subject,200)||E'\n\n'||_message,CASE WHEN _source='email' THEN 'email' ELSE 'web' END); INSERT INTO public.support_ticket_messages(ticket_id,author,body) VALUES(t.id,'system','You already have an active support ticket. We have added this request here so all your messages stay together. Continue replying on ticket #'||t.number||'. You can open another ticket after this conversation is resolved or closed.'); UPDATE public.support_tickets SET status='open',last_customer_reply_at=now(),reminder_sent_at=NULL,updated_at=now() WHERE id=t.id RETURNING * INTO t; RETURN jsonb_build_object('ticket',to_jsonb(t),'appended',true); END IF; INSERT INTO public.support_tickets(account_id,requester_email,requester_name,subject,topic,source,previous_ticket_id,last_customer_reply_at) VALUES(_account_id,lower(trim(_email)),_name,left(_subject,200),_topic,_source,_previous,now()) RETURNING * INTO t; INSERT INTO public.support_ticket_messages(ticket_id,author,body,via) VALUES(t.id,'customer',_message,CASE WHEN _source='email' THEN 'email' ELSE 'web' END); RETURN jsonb_build_object('ticket',to_jsonb(t),'appended',false); END $$;
REVOKE ALL ON FUNCTION public.create_or_append_support_ticket(uuid,text,text,text,text,text,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.create_or_append_support_ticket(uuid,text,text,text,text,text,text,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.merge_support_ticket(_source uuid,_target uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.support_tickets; t public.support_tickets; explanation text; BEGIN IF _source=_target THEN RAISE EXCEPTION 'Choose two different tickets'; END IF; PERFORM id FROM public.support_tickets WHERE id IN (_source,_target) ORDER BY id FOR UPDATE; SELECT * INTO s FROM public.support_tickets WHERE id=_source; SELECT * INTO t FROM public.support_tickets WHERE id=_target; IF s.id IS NULL OR t.id IS NULL THEN RAISE EXCEPTION 'Ticket not found'; END IF; IF s.merged_into_ticket_id=_target THEN RETURN jsonb_build_object('source',to_jsonb(s),'target',to_jsonb(t),'already_merged',true); END IF; IF s.status NOT IN ('open','waiting') OR t.status NOT IN ('open','waiting') OR s.merged_into_ticket_id IS NOT NULL OR t.merged_into_ticket_id IS NOT NULL THEN RAISE EXCEPTION 'Both tickets must be unresolved'; END IF; IF s.account_id IS DISTINCT FROM t.account_id OR lower(s.requester_email)<>lower(t.requester_email) THEN RAISE EXCEPTION 'Tickets must belong to the same business and requester'; END IF; explanation:='We have combined ticket #'||s.number||' with ticket #'||t.number||' so all your requests and replies stay in one conversation. Ticket #'||s.number||' is now closed. Please continue on ticket #'||t.number||'. No messages or attachments have been lost.'; INSERT INTO public.support_ticket_messages(ticket_id,author,body) VALUES(t.id,'system','Conversation imported from ticket #'||s.number||': '||s.subject); INSERT INTO public.support_ticket_messages(ticket_id,author,author_user_id,body,internal,via,created_at,attachments) SELECT t.id,author,author_user_id,body,internal,via,created_at,attachments FROM public.support_ticket_messages WHERE ticket_id=s.id; INSERT INTO public.support_ticket_messages(ticket_id,author,body) VALUES(t.id,'system',explanation),(s.id,'system',explanation); UPDATE public.support_tickets SET status='closed',closed_at=now(),updated_at=now(),merged_into_ticket_id=t.id WHERE id=s.id; UPDATE public.support_tickets SET status='open',last_customer_reply_at=now(),reminder_sent_at=NULL,updated_at=now() WHERE id=t.id RETURNING * INTO t; RETURN jsonb_build_object('source',to_jsonb(s),'target',to_jsonb(t),'explanation',explanation,'already_merged',false); END $$;
REVOKE ALL ON FUNCTION public.merge_support_ticket(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.merge_support_ticket(uuid,uuid) TO service_role;